head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vRowCount = 0;
scwin.isCopy = true;
scwin.processGp; // 접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 숨기기
        grd_ExcelList.hide();
        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_Acpt);
        // 스트립조회
        scwin.searchStrip();
        // 목록 조회
        scwin.listSync();
        // 1분 자동갱신
        // fn_RefreshForm(60000);
        // 팀장확인데이터셋설정

        // dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_Temp.insertRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10200.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        scwin.vRowCount = rowcount;
        if (rowcount > 0) {
            if (dts_List.getCellData(1, 'INTEG_RSLT_CNT') > 0) {
                btn_Proc.setBackgroundImage("../img/bns/btn_20_d.gif");
                btn_Proc.setDisabled(true);
            } else {
                btn_Proc.setBackgroundImage("../img/bns/btn_20.gif");
                btn_Proc.setDisabled(false);
            }
        }

        // 헤더 복제
        if (scwin.isCopy) {
            scwin.isCopy = false;
            // 저장
            $c.stf.copyDataSetHeader(dts_List, dts_Save);
            // 결재파일
            const sbmOptions = {
                id : "sbm_dts_ExcelList",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_ExcelList=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10200.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        if (scwin.processGp === '3') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
        } else if (scwin.processGp === '4') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "취소"));
        } else if (scwin.processGp === '6') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
        } else {
            await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10200.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (scwin.processGp === '3') {
            await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        } else if (scwin.processGp === '4') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "취소"));
        } else if (scwin.processGp === '6') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
        }
        scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10200.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_ApprovFileCreat_onclick
 * @description 「결재파일생성」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ApprovFileCreat_onclick = function() {
    try {
        if (scwin.vRowCount === 0) return;
        scwin.approvFileCreat();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10200.btn_ApprovFileCreat_onclick" });
    }
};

/**
 * @method
 * @name btn_Proc_onclick
 * @description 「처리완료」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Proc_onclick = async function() {
    try {
        await scwin.procsComplt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10200.btn_Proc_onclick" });
    }
};

/**
 * @method
 * @name btn_Cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cancel_onclick = async function() {
    try {
        if (scwin.vRowCount === 0) return;
        await scwin.cancel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10200.btn_Cancel_onclick" });
    }
};

/**
 * @method
 * @name btn_TeamleadrConfrm_onclick
 * @description 「팀장확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_TeamleadrConfrm_onclick = async function() {
    try {
        if (scwin.vRowCount === 0) return;
        if (js_jobtitl === '03' && (js_duty === 'N' && js_duty_chrg === 'N')) {
            await $c.win.alert('팀장권한만 가능합니다.');
            return;
        }
        await scwin.teamleadrConfrm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10200.btn_TeamleadrConfrm_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDBNS10200.xml', SCREN_PROCS_TP_CD_07);
        const fileNm = $c.ut.cGetToday("yyyymmdd") + '_' + '스트립통합처리';
        $c.data.downloadGridViewExcel(grd_List, {fileName: "스트립통합처리", type: 8});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10200.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_1_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_1_onclick = function() {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10200.btn_Search_1_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description 스트립통합목록을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    // 목록조회
    let param = '';
    let dsNm = 'BNS_STRIP_INTEG';
    let qryId = 'lds.stf.bnschg.select.listStripInteg';
    $c.bns.fn_SearchBns('ULDBNS10200.xml', dts_List, dsNm, qryId, param);
};

// 자동갱신
// function fn_RefreshForm(interval) {
//    setInterval("fn_list_sync();", interval);
// }

/**
 * @method
 * @name searchStrip
 * @description 스트립통합 대상을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchStrip = function() {
    let param = '';
    let dsNm = 'BNS_STRIP_INTEG';
    let qryId = 'lds.stf.bnschg.select.listStripIntegTarget';
    $c.bns.fn_SearchBns('ULDBNS10200.xml', dts_StripInfo, dsNm, qryId, param);
};

/**
 * @method
 * @name searchStripIntegSeq
 * @description 스트립통합 일련번호 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchStripIntegSeq = function() {
    let param = '';
    let dsNm = 'BNS_COM_CD';
    let qryId = 'lds.stf.bnschg.select.readStripIntegTargetSeq';
    dts_Temp.SyncLoad = true;
    $c.bns.fn_SearchBns('ULDBNS10200.xml', dts_Temp, dsNm, qryId, param);
};

/**
 * @method
 * @name procsComplt
 * @description 처리완료 및 수정을 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procsComplt = async function() {
    // 통합처리 리스트 갱신
    scwin.listSync();
    // 스트립조회
    scwin.searchStrip();

    // sleep(3000);

    // 미처리건 확인
    let param = '';
    let dsNm = 'BNS_COM_CD';
    let qryId = 'lds.stf.bnschg.select.readStripInteg';
    dts_Temp.SyncLoad = true;
    $c.bns.fn_SearchBns('ULDBNS10200.xml', dts_Temp, dsNm, qryId, param);
    if (dts_Temp.getCellData(1, 'VALUE') > 0) {
        await $c.win.alert('스트립 미처리건이 존재합니다. 미처리건을 확인하여 주십시요.\n\n대상화면: 스트립신규[BNS10000], 스트립추가및재결합[BNS10100]');
        return;
    }

    // 통합처리 대상건이 없을경우
    if (scwin.vRowCount === 0) {
        await $c.win.alert('스트립 통합처리 대상이 존재하지 않습니다.');
        return;
    }
    scwin.processGp = '3';
    if (!confirm("처리 하시겠습니까?")) return;

    // 이자만 추가한다.
    dts_Save.removeAll();

    // 일련번호채번
    scwin.searchStripIntegSeq();
    dts_Save.setBroadcast(false);
    for (let stripIdx = 1; stripIdx <= dts_StripInfo.getRowCount(); stripIdx++) {
        for (let idx = 1; idx <= dts_List.getRowCount(); idx++) {
            if (dts_List.getCellData(idx, 'STRIP_TP_CD') === '3') {
                dts_Save.insertRow();
                // 스트립통합 대상
                dts_Save.setCellData(dts_Save.getRowPosition(), 'BND_APPL_ID', dts_StripInfo.getCellData(stripIdx, 'BND_APPL_ID'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'STRIP_ORGN_ISU_CD', dts_StripInfo.getCellData(stripIdx, 'STRIP_ORGN_ISU_CD'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'SEQ', dts_Temp.getCellData(1, 'VALUE'));
                // 스트립통합 이자
                dts_Save.setCellData(dts_Save.getRowPosition(), 'STD_CD', dts_List.getCellData(idx, 'STD_CD'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'BF_LIST_AMT', dts_List.getCellData(idx, 'BF_LIST_AMT'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'SPRT_PAR_AMT', dts_List.getCellData(idx, 'SPRT_PAR_AMT'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'RECOMBIN_PAR_AMT', dts_List.getCellData(idx, 'RECOMBIN_PAR_AMT'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'AF_LIST_AMT', dts_List.getCellData(idx, 'AF_LIST_AMT'));
            }
        }
    }
    dts_Save.setBroadcast(true, true);
    // alert(dts_Save.CountRow);

    let url = "/bns/Strip.do?method=processStripIntegProcessComplt";
    url += "&SCREN_ID=" + 'ULDBNS10200.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
    trs_Save.Post();
};

/**
 * @method
 * @name teamleadrConfrm
 * @description 팀장확인을 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.teamleadrConfrm = async function() {
    if (scwin.vRowCount === 0) return;
    scwin.processGp = "6";
    if (dts_List.getCellData(1, 'INTEG_RSLT_CNT') === 0) {
        await $c.win.alert('팀장확인은 처리완료 후 가능합니다.');
        return;
    }
    if (!window.confirm("팀장확인처리일자가 시장지파일 전송일자입니다. \n 팀장확인처리하시겠습니까?")) return;

    // 변경된 데이터가 없으면 Action이 호출되지 않음.
    // 따라서 Row를 추가함.
    dts_Temp.insertRow();
    let url = "/bns/Strip.do?method=processTeamleadrConfrm";
    url += "&SCREN_ID=" + 'ULDBNS10200.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Post();
};

/**
 * @method
 * @name cancel
 * @description 취소를 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cancel = async function() {
    if (scwin.vRowCount === 0) return;
    scwin.processGp = "4";

    // 취소가능체크
    if (dts_List.getCellData(1, 'INTEG_RSLT_CNT') === 0) {
        await $c.win.alert('취소는 처리완료 후 가능합니다.');
        return;
    }

    // 마감체크
    let param = '';
    let dsNm = 'BNS_COM_CD';
    let qryId = 'lds.stf.bnschg.select.readStripIntegCls';
    dts_Temp.SyncLoad = true;
    $c.bns.fn_SearchBns('ULDBNS10200.xml', dts_Temp, dsNm, qryId, param);
    if (dts_Temp.getRowCount() > 0 &&
        dts_Temp.getCellData(1, 'VALUE') > 0) {
        await $c.win.alert('채권마감 후 사용이 불가능합니다.');
        return;
    }
    if (!confirm("처리 하시겠습니까?")) return;
    dts_Temp.insertRow();
    let url = "/bns/Strip.do?method=processCancel";
    url += "&SCREN_ID=" + 'ULDBNS10200.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Post();
};

/**
 * @method
 * @name approvFileCreat
 * @description 결재파일생성
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.approvFileCreat = function(arrPar) {
    if (dts_List.getRowCount() === 0) return;
    let url = "/bns/BnsApprovFileDownload.do?";
    url += "BND_MKTACT_TP_CD=405";
    location.href = url;
};

/**
 * @method
 * @name sleep
 * @description process wait state 함수 - numberMillis 수치만큼 wait.
 * @param {*} numberMillis numberMillis
 * @returns {void}
 * @hidden N
 */
scwin.sleep = function(numberMillis) {
    let now = new Date();
    const exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};
